#!/usr/bin/env python3
"""Settings support for the PuddleDuck web UI.

Network ownership stays with the BDX overlay:

* /etc/default/bdx-network contains image defaults and fixed topology.
* /data/etc/bdx-network contains persistent operator choices.
* bdx-set-body-wifi owns the body's multi-network Wi-Fi profile database.
* bdx-set-head-ap owns the head access point settings.

This module is only a web adapter around those canonical tools.  It does not
create NetworkManager profiles or maintain a second settings database.
"""

from __future__ import annotations

import http.client
import json
import os
import shutil
import socket
import subprocess
import threading
import time
from pathlib import Path
from typing import Any, Callable, Dict, List, Optional, Tuple, Union
from urllib.parse import quote

try:
    from pd.runtime.wifi_security import classify_advertised_security, is_wpa3_key_mgmt
except ModuleNotFoundError:
    # Several source-tree tests load this file directly instead of importing the
    # pd.runtime package. Load the sibling helper explicitly for that case.
    import importlib.util

    _wifi_security_path = Path(__file__).with_name("wifi_security.py")
    _wifi_security_spec = importlib.util.spec_from_file_location(
        "puddleduck_wifi_security",
        _wifi_security_path,
    )
    if _wifi_security_spec is None or _wifi_security_spec.loader is None:
        raise
    _wifi_security_module = importlib.util.module_from_spec(_wifi_security_spec)
    _wifi_security_spec.loader.exec_module(_wifi_security_module)
    classify_advertised_security = _wifi_security_module.classify_advertised_security
    is_wpa3_key_mgmt = _wifi_security_module.is_wpa3_key_mgmt

DEFAULT_WEB_SETTINGS_PATH = "~/.config/puddleduck/settings.json"
DEFAULT_VIEWER_DUCK_PATH = "~/.config/puddleduck/viewer.json"
BODY_WIFI_CLI = "/usr/local/bin/bdx-set-body-wifi"
UPDATE_HELPER = "/usr/local/sbin/puddleduck-bdx-update"
DUCK_PASSWORD_HELPER = "/usr/local/sbin/puddleduck-set-duck-password"
MDNS_HELPER = "/usr/local/sbin/puddleduck-set-mdns-name"
DEFAULT_DUCK_NAME = "Duckling"
BDX_HEAD_NAME = "bdx-head"
BDX_HEAD_ETHERNET_IP = "192.168.50.1"
BDX_BODY_ETHERNET_IP = "192.168.50.2"
BDX_HEAD_SETTINGS_PORT = 8081
BDX_WEB_PORT = 8080
SETTINGS_API_VERSION = 5
VIEWER_DUCK_FILE_VERSION = 1
DEFAULT_REMEMBERED_DUCKS = ("besh", "grek", "oskar", "red")


class HeadSettingsError(RuntimeError):
    """Error returned by the private head settings service."""

    def __init__(self, message: str, status: int = 502):
        super().__init__(message)
        self.status = status if 400 <= int(status) <= 599 else 502


def _head_settings_error(response: Dict[str, Any], fallback: str) -> HeadSettingsError:
    payload = response.get("payload") if isinstance(response.get("payload"), dict) else {}
    message = str(payload.get("message") or response.get("message") or fallback)
    return HeadSettingsError(message, int(response.get("status") or 502))


def _load_identity(path: str) -> Dict[str, str]:
    try:
        with open(path, "r", encoding="utf-8") as stream:
            value = json.load(stream)
    except FileNotFoundError:
        return {"duck_name": DEFAULT_DUCK_NAME}
    except Exception as ex:
        print(f"[web] settings load failed {path}: {ex}", flush=True)
        return {"duck_name": DEFAULT_DUCK_NAME}
    if not isinstance(value, dict):
        return {"duck_name": DEFAULT_DUCK_NAME}
    return {"duck_name": str(value.get("duck_name") or "").strip() or DEFAULT_DUCK_NAME}


def _atomic_write_json(path: Union[str, Path], value: Dict[str, Any]) -> None:
    target = Path(path).expanduser()
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_name(f".{target.name}.tmp")
    with open(temporary, "w", encoding="utf-8") as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write("\n")
        stream.flush()
        os.fsync(stream.fileno())
    os.chmod(temporary, 0o600)
    os.replace(temporary, target)
    os.chmod(target, 0o600)


def _save_identity(path: str, duck_name: str) -> None:
    _atomic_write_json(path, {"duck_name": duck_name})


class DuckSelectionStore:
    """Persist the viewer's named Duck on the body, not in a browser.

    On BDX images the ``duck`` user's home is ``/data/home/duck``, so the
    default file survives rootfs updates and is shared by every browser that
    connects to this PuddleDuck.
    """

    def __init__(
        self,
        path: Optional[str] = None,
        *,
        remembered_ducks: Tuple[str, ...] = DEFAULT_REMEMBERED_DUCKS,
    ):
        configured = (
            path
            or os.environ.get("PUDDLEDUCK_VIEWER_DUCK_PATH")
            or DEFAULT_VIEWER_DUCK_PATH
        )
        self.path = Path(configured).expanduser()
        self.remembered_ducks = tuple(
            dict.fromkeys(str(value or "").strip().lower() for value in remembered_ducks)
        )
        self._remembered = frozenset(value for value in self.remembered_ducks if value)
        self._lock = threading.RLock()

    def normalize(self, value: Any) -> str:
        duck = str(value or "auto").strip().lower()
        if duck == "auto" or duck in self._remembered:
            return duck
        choices = ", ".join(("auto", *self.remembered_ducks))
        raise ValueError(f"viewer duck must be one of: {choices}")

    def load(self) -> str:
        with self._lock:
            try:
                value = json.loads(self.path.read_text(encoding="utf-8"))
            except FileNotFoundError:
                return "auto"
            except Exception as ex:
                print(f"[web] viewer Duck selection load failed {self.path}: {ex}", flush=True)
                return "auto"

            if isinstance(value, str):
                raw_duck = value
            elif isinstance(value, dict):
                raw_duck = value.get("duck", "auto")
            else:
                return "auto"

            duck = str(raw_duck or "auto").strip().lower()
            return duck if duck == "auto" or duck in self._remembered else "auto"

    def save(self, value: Any) -> Dict[str, Any]:
        duck = self.normalize(value)
        with self._lock:
            _atomic_write_json(
                self.path,
                {
                    "version": VIEWER_DUCK_FILE_VERSION,
                    "duck": duck,
                },
            )
        return {
            "ok": True,
            "duck": duck,
            "path": str(self.path),
            "message": (
                "Viewer Duck selection reset to Auto on this PuddleDuck."
                if duck == "auto"
                else f"Viewer Duck {duck.title()} saved on this PuddleDuck."
            ),
        }


def _command(
    args: List[str],
    *,
    timeout: float = 15.0,
    input_text: Optional[str] = None,
) -> Dict[str, Any]:
    try:
        completed = subprocess.run(
            [str(item) for item in args],
            input=input_text,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False,
            timeout=float(timeout),
            env={
                **os.environ,
                "PATH": "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
                "LANG": "C",
                "LC_ALL": "C",
            },
        )
    except FileNotFoundError as ex:
        return {"ok": False, "message": f"command not found: {args[0]}", "error": str(ex)}
    except subprocess.TimeoutExpired:
        return {"ok": False, "message": f"command timed out: {Path(args[0]).name}"}

    stdout = (completed.stdout or "").strip()
    stderr = (completed.stderr or "").strip()
    return {
        "ok": completed.returncode == 0,
        "returncode": int(completed.returncode),
        "stdout": stdout,
        "stderr": stderr,
        "message": stderr or stdout,
    }


def _last_json_object(text: str) -> Dict[str, Any]:
    for line in reversed(str(text or "").splitlines()):
        try:
            value = json.loads(line)
        except Exception:
            continue
        if isinstance(value, dict):
            return value
    return {}


def _json_http(
    address: str,
    port: int,
    method: str,
    path: str,
    *,
    payload: Optional[Dict[str, Any]] = None,
    timeout: float = 1.5,
) -> Dict[str, Any]:
    body = None
    headers = {
        "Accept": "application/json",
        "Connection": "close",
        "Host": f"{BDX_HEAD_NAME}:{int(port)}",
    }
    if payload is not None:
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        headers["Content-Type"] = "application/json"
        headers["Content-Length"] = str(len(body))

    connection = http.client.HTTPConnection(address, int(port), timeout=float(timeout))
    try:
        connection.request(method, path, body=body, headers=headers)
        response = connection.getresponse()
        raw = response.read(64 * 1024)
        try:
            decoded = json.loads(raw.decode("utf-8")) if raw else {}
        except Exception:
            decoded = {}
        if not isinstance(decoded, dict):
            decoded = {}
        ok = 200 <= int(response.status) < 300 and decoded.get("ok", True) is not False
        return {
            "ok": bool(ok),
            "status": int(response.status),
            "payload": decoded,
            "message": str(decoded.get("message") or f"HTTP {int(response.status)}"),
        }
    except (OSError, http.client.HTTPException) as ex:
        return {"ok": False, "status": 0, "payload": {}, "message": str(ex)}
    finally:
        connection.close()


def _split_nmcli(line: str) -> List[str]:
    fields: List[str] = []
    current: List[str] = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == ":":
            fields.append("".join(current))
            current = []
        else:
            current.append(char)
    fields.append("".join(current))
    return fields


def _truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "on"}


class PuddleDuckSettingsManager:
    """Expose BDX settings without duplicating BDX network state."""

    def __init__(self):
        self.path = os.path.expanduser(DEFAULT_WEB_SETTINGS_PATH)
        os.makedirs(os.path.dirname(self.path) or ".", exist_ok=True)
        self.body_wifi_cli = BODY_WIFI_CLI
        self._identity_lock = threading.RLock()
        self._job_lock = threading.Lock()
        self._job_serial = 0
        self._job: Dict[str, Any] = {
            "id": 0,
            "state": "idle",
            "component": "",
            "message": "No settings operation is running.",
            "started_at": None,
            "finished_at": None,
        }

    @staticmethod
    def _plain_text(value: Any, key: str, *, max_len: int, required: bool = False) -> str:
        text = str(value or "").strip()
        if any(char in text for char in "\r\n\0"):
            raise ValueError(f"{key} contains an invalid control character")
        if required and not text:
            raise ValueError(f"{key} is required")
        if len(text) > max_len:
            raise ValueError(f"{key} is too long")
        return text

    @classmethod
    def _ssid(cls, value: Any, *, required: bool = True) -> str:
        text = cls._plain_text(value, "ssid", max_len=128, required=required)
        if len(text.encode("utf-8")) > 32:
            raise ValueError("SSID must be at most 32 UTF-8 bytes")
        return text

    @classmethod
    def _head_ap_name(cls, value: Any) -> str:
        text = cls._plain_text(value, "head access-point name", max_len=128, required=True)
        # The generated SSID appends one space and four hexadecimal characters.
        if len(text.encode("utf-8")) > 27:
            raise ValueError("head access-point name must be at most 27 UTF-8 bytes")
        return text

    @staticmethod
    def _psk(value: Any, key: str, *, allow_empty: bool = True) -> str:
        text = str(value or "")
        if any(char in text for char in "\r\n\0"):
            raise ValueError(f"{key} contains an invalid control character")
        if not text and allow_empty:
            return ""
        if len(text) == 64 and all(char in "0123456789abcdefABCDEF" for char in text):
            return text
        if not 8 <= len(text) <= 63:
            raise ValueError(f"{key} must contain 8-63 characters, or 64 hexadecimal digits")
        return text

    @staticmethod
    def _priority(value: Any) -> int:
        try:
            priority = int(value)
        except (TypeError, ValueError) as ex:
            raise ValueError("priority must be an integer") from ex
        if priority < -999 or priority > 999:
            raise ValueError("priority must be between -999 and 999")
        return priority

    def _body_wifi_command(
        self,
        arguments: List[str],
        *,
        input_text: Optional[str] = None,
        timeout: float = 90.0,
    ) -> Dict[str, Any]:
        helper = Path(self.body_wifi_cli)
        if not helper.is_file() or not os.access(str(helper), os.X_OK):
            raise RuntimeError(f"body Wi-Fi command is not installed: {self.body_wifi_cli}")

        command = [self.body_wifi_cli, *arguments]
        if os.geteuid() != 0:
            sudo = shutil.which("sudo")
            if not sudo:
                raise RuntimeError("sudo is not installed")
            command = [sudo, "-n", *command]

        result = _command(command, input_text=input_text, timeout=timeout)
        parsed = _last_json_object(result.get("stdout") or result.get("stderr") or "")
        if not result.get("ok") or parsed.get("ok") is False:
            detail = str(parsed.get("message") or result.get("message") or "body Wi-Fi command failed")
            raise RuntimeError(detail)
        if not parsed:
            raise RuntimeError("body Wi-Fi command returned no JSON result")
        return parsed

    def _body_profiles(self) -> Dict[str, Any]:
        try:
            result = self._body_wifi_command(["--show", "--json"], timeout=12.0)
            profiles = result.get("profiles") if isinstance(result.get("profiles"), list) else []
            active_security = result.get("active_security") if isinstance(result.get("active_security"), dict) else {}
            policy = result.get("policy") if isinstance(result.get("policy"), dict) else {}
            return {
                "available": True,
                "profiles": profiles,
                "active_security": active_security,
                "policy": policy,
                "message": "",
            }
        except Exception as ex:
            return {
                "available": False,
                "profiles": [],
                "active_security": {},
                "policy": {},
                "message": str(ex),
            }

    @staticmethod
    def _wifi_rows(*, rescan: bool) -> List[Dict[str, Any]]:
        nmcli = shutil.which("nmcli")
        if not nmcli:
            raise RuntimeError("nmcli is not installed")
        result = _command(
            [
                nmcli,
                "--terse",
                "--escape",
                "yes",
                "--fields",
                "IN-USE,SSID,SIGNAL,SECURITY,DEVICE",
                "device",
                "wifi",
                "list",
                "--rescan",
                "yes" if rescan else "no",
            ],
            timeout=18.0 if rescan else 5.0,
        )
        if not result.get("ok"):
            raise RuntimeError(result.get("message") or "nmcli Wi-Fi query failed")

        best: Dict[Tuple[str, str], Dict[str, Any]] = {}
        for line in str(result.get("stdout") or "").splitlines():
            fields = _split_nmcli(line)
            if len(fields) < 5 or not fields[1]:
                continue
            active, ssid, signal, security, device = fields[:5]
            try:
                signal_value = max(0, min(100, int(float(signal or 0))))
            except Exception:
                signal_value = 0
            row = {
                "active": active.strip().lower() in {"*", "yes", "true"},
                "ssid": ssid,
                "signal": signal_value,
                "security": security,
                "device": device,
                **classify_advertised_security(security),
            }
            key = (ssid, security)
            prior = best.get(key)
            if prior is None or row["active"] or signal_value > int(prior.get("signal", 0)):
                best[key] = row
        return sorted(best.values(), key=lambda item: (not item["active"], -item["signal"], item["ssid"].lower()))

    @staticmethod
    def _active_wifi_connection() -> Dict[str, Any]:
        """Return the active Wi-Fi connection without requiring a scan.

        `nmcli device wifi list` can be unavailable to an unprivileged service
        even while NetworkManager has a perfectly healthy active connection.
        Device status is a cheaper and more reliable source for the current
        connection; scan results are only used later to enrich signal/security.
        """
        nmcli = shutil.which("nmcli")
        if not nmcli:
            raise RuntimeError("nmcli is not installed")

        result = _command(
            [
                nmcli,
                "--terse",
                "--escape",
                "yes",
                "--fields",
                "DEVICE,TYPE,STATE,CONNECTION",
                "device",
                "status",
            ],
            timeout=5.0,
        )
        if not result.get("ok"):
            raise RuntimeError(result.get("message") or "nmcli device status failed")

        for line in str(result.get("stdout") or "").splitlines():
            fields = _split_nmcli(line)
            if len(fields) < 4:
                continue
            device, device_type, state, connection_name = fields[:4]
            if device_type.strip().lower() != "wifi":
                continue
            state_text = state.strip().lower()
            if not state_text.startswith("connected"):
                continue

            ssid = ""
            if connection_name and connection_name != "--":
                ssid_result = _command(
                    [nmcli, "--get-values", "802-11-wireless.ssid", "connection", "show", connection_name],
                    timeout=4.0,
                )
                if ssid_result.get("ok"):
                    ssid = str(ssid_result.get("stdout") or "").splitlines()[0].strip() if str(ssid_result.get("stdout") or "").splitlines() else ""

            return {
                "active": True,
                "device": device,
                "connection": connection_name if connection_name != "--" else "",
                "ssid": ssid or (connection_name if connection_name != "--" else ""),
                "signal": None,
                "security": "",
                **classify_advertised_security(""),
            }

        return {}

    @staticmethod
    def _interface_addresses(device: str) -> List[str]:
        if not device:
            return []
        ip = shutil.which("ip")
        if not ip:
            return []
        result = _command([ip, "-j", "-4", "address", "show", "dev", device], timeout=3.0)
        if not result.get("ok"):
            return []
        try:
            entries = json.loads(result.get("stdout") or "[]")
        except Exception:
            return []
        return [
            f"{info['local']}/{info.get('prefixlen', '')}".rstrip("/")
            for entry in entries
            for info in entry.get("addr_info", [])
            if info.get("family") == "inet" and info.get("local")
        ]

    def _body_wifi_snapshot(self) -> Dict[str, Any]:
        stored = self._body_profiles()
        try:
            active = self._active_wifi_connection() or None
            active_message = ""
        except Exception as ex:
            active = None
            active_message = str(ex)

        # Reading the passive list as the service user is useful for current
        # signal/security details, but an active rescan is performed by the
        # canonical privileged bdx-set-body-wifi command.  Do not disable the
        # Scan button merely because an unprivileged passive nmcli query failed.
        try:
            rows = self._wifi_rows(rescan=False)
            scan_message = ""
        except Exception as ex:
            rows = []
            scan_message = str(ex)
        scan_available = bool(stored.get("available"))

        scanned_active = next((row for row in rows if row.get("active")), None)
        if scanned_active:
            if active:
                active.update({
                    "ssid": scanned_active.get("ssid") or active.get("ssid"),
                    "signal": scanned_active.get("signal"),
                    "security": scanned_active.get("security") or active.get("security"),
                    "security_mode": scanned_active.get("security_mode"),
                    "wpa3": bool(scanned_active.get("wpa3")),
                    "wpa3_only": bool(scanned_active.get("wpa3_only")),
                    "transition": bool(scanned_active.get("transition")),
                    "supported": bool(scanned_active.get("supported", True)),
                    "warning": str(scanned_active.get("warning") or ""),
                })
            else:
                active = dict(scanned_active)
        visible_by_ssid: Dict[str, Dict[str, Any]] = {}
        for row in rows:
            ssid = str(row.get("ssid") or "")
            if not ssid:
                continue
            prior = visible_by_ssid.get(ssid)
            if prior is None or row.get("active") or int(row.get("signal") or 0) > int(prior.get("signal") or 0):
                visible_by_ssid[ssid] = row

        profiles: List[Dict[str, Any]] = []
        for raw in stored.get("profiles", []):
            if not isinstance(raw, dict):
                continue
            profile = dict(raw)
            ssid = str(profile.get("ssid") or "")
            visible = visible_by_ssid.get(ssid)
            security_text = str((visible or {}).get("security") or ("open" if profile.get("open") else "saved"))
            classification = (
                {key: visible.get(key) for key in (
                    "security_mode", "wpa3", "wpa3_only", "transition", "supported", "warning"
                )}
                if visible is not None
                else classify_advertised_security(security_text)
            )
            profile.update({
                "active": bool(active and active.get("ssid") == ssid),
                "visible": visible is not None,
                "signal": int((visible or {}).get("signal") or 0),
                "security": security_text,
                **classification,
            })
            profiles.append(profile)
        profiles.sort(key=lambda item: (-int(item.get("priority") or 0), str(item.get("ssid") or "").lower()))

        current = dict(active or {})
        active_security = stored.get("active_security") if isinstance(stored.get("active_security"), dict) else {}
        key_mgmt = str(active_security.get("key_mgmt") or "")
        if key_mgmt:
            current["key_mgmt"] = key_mgmt
        current["wpa3_active"] = bool(active_security.get("wpa3_active")) or is_wpa3_key_mgmt(key_mgmt)
        if current.get("wpa3_active"):
            current["supported"] = False
            current["warning"] = (
                "Unsupported WPA3 security was detected and the connection is being blocked. "
                "Use WPA2 or WPA2/WPA3 transition mode."
            )
        current["addresses"] = self._interface_addresses(str(current.get("device") or ""))

        policy = stored.get("policy") if isinstance(stored.get("policy"), dict) else {}
        if not policy:
            policy = {
                "mode": "wpa2-only",
                "wpa3_allowed": False,
                "transition_allowed": True,
            }
        message = str(stored.get("message") or active_message or scan_message)
        if current.get("wpa3_active"):
            message = str(current.get("warning") or message)
        return {
            "available": bool(stored.get("available")),
            "message": message,
            "scan_available": scan_available,
            "policy": policy,
            "current": current,
            "profiles": profiles,
        }

    def _head_snapshot(self) -> Dict[str, Any]:
        settings_response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "GET",
            "/settings",
            timeout=1.5,
        )
        head_ap: Dict[str, Any] = {}
        if settings_response.get("ok"):
            settings = (settings_response.get("payload") or {}).get("settings")
            if isinstance(settings, dict) and isinstance(settings.get("head_ap"), dict):
                head_ap = dict(settings["head_ap"])

        # Query the dedicated endpoint so a present-but-unresponsive QuackHead
        # is distinguished from simple USB enumeration. The /system response
        # intentionally carries only a cheap presence snapshot.
        hardware = self.head_hardware_status()

        proxy_response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_WEB_PORT,
            "GET",
            "/api/config",
            timeout=1.5,
        )
        return {
            "host": BDX_HEAD_NAME,
            "address": BDX_HEAD_ETHERNET_IP,
            "settings_service": {
                "reachable": bool(settings_response.get("ok")),
                "port": BDX_HEAD_SETTINGS_PORT,
                "message": "connected" if settings_response.get("ok") else str(settings_response.get("message") or "unavailable"),
            },
            "access_point": head_ap,
            "hardware": hardware,
            "proxy": {
                "reachable": bool(proxy_response.get("ok")),
                "port": BDX_WEB_PORT,
                "message": "connected" if proxy_response.get("ok") else str(proxy_response.get("message") or "unavailable"),
            },
        }

    def head_hardware_status(self) -> Dict[str, Any]:
        """Return the QuackHead controller status from the private head service."""
        response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "GET",
            "/hardware",
            timeout=2.5,
        )
        if response.get("ok"):
            payload = response.get("payload") or {}
            quackhead = payload.get("quackhead") if isinstance(payload, dict) else None
            if isinstance(quackhead, dict):
                result = dict(quackhead)
                result.setdefault("ok", True)
                result.setdefault("component", "quackhead")
                result.setdefault("label", "QuackHead")
                result.setdefault("present", bool(result.get("device_present")))
                result.setdefault("complete", bool(result.get("responding")))
                result.setdefault("device_present", bool(result.get("present")))
                result["head_reachable"] = True
                return result
        return {
            "ok": True,
            "component": "quackhead",
            "label": "QuackHead",
            "present": False,
            "complete": False,
            "responding": False,
            "device_present": False,
            "state": "head-unavailable",
            "head_reachable": False,
            "message": str(response.get("message") or "Head settings service is unavailable."),
            "devices": {},
        }

    def head_system_status(self) -> Dict[str, Any]:
        """Return head power status through the private robot-Ethernet service."""
        response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "GET",
            "/system",
            timeout=1.5,
        )
        if response.get("ok"):
            payload = response.get("payload") or {}
            if isinstance(payload, dict):
                actions = payload.get("actions") if isinstance(payload.get("actions"), dict) else {}
                return {
                    "ok": True,
                    "reachable": True,
                    "role": "head",
                    "host": str(payload.get("host") or BDX_HEAD_NAME),
                    "uptime_s": payload.get("uptime_s"),
                    "bdx": dict(payload.get("bdx") or {}) if isinstance(payload.get("bdx"), dict) else {},
                    "pending_action": str(payload.get("pending_action") or ""),
                    "hardware": dict(payload.get("hardware") or {}) if isinstance(payload.get("hardware"), dict) else {},
                    "actions": {
                        "reboot": {"available": bool((actions.get("reboot") or {}).get("available"))},
                        "recovery": {"available": bool((actions.get("recovery") or {}).get("available"))},
                        "shutdown": {"available": bool((actions.get("shutdown") or {}).get("available"))},
                    },
                    "message": str(payload.get("message") or "Head power controls are ready."),
                }
        return {
            "ok": True,
            "reachable": False,
            "role": "head",
            "host": BDX_HEAD_NAME,
            "uptime_s": None,
            "bdx": {},
            "pending_action": "",
            "hardware": {
                "ok": True,
                "component": "QuackHead",
                "role": "head",
                "state": "unreachable",
                "responding": False,
                "device_present": False,
                "message": str(response.get("message") or "head settings service is unavailable"),
            },
            "actions": {
                "reboot": {"available": False},
                "recovery": {"available": False},
                "shutdown": {"available": False},
            },
            "message": str(response.get("message") or "head settings service is unavailable"),
        }

    def request_head_power(self, action: str) -> Tuple[Dict[str, Any], int]:
        """Ask the root-owned private head service to reboot, recover, or power off."""
        action = str(action or "").strip().lower()
        if action not in ("reboot", "recovery", "shutdown"):
            return {"ok": False, "message": f"unsupported head power action: {action}"}, 404
        response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "POST",
            f"/system/{action}",
            payload={},
            timeout=4.0,
        )
        payload = response.get("payload") if isinstance(response.get("payload"), dict) else {}
        if not response.get("ok"):
            status = int(response.get("status") or 503)
            if status < 400 or status > 599:
                status = 503
            return {
                "ok": False,
                "message": str(payload.get("message") or response.get("message") or f"head {action} request failed"),
            }, status
        result = dict(payload)
        result.setdefault("ok", True)
        result.setdefault("host", BDX_HEAD_NAME)
        result.setdefault("action", action)
        result.setdefault("message", f"head {action} scheduled")
        status = int(response.get("status") or 202)
        return result, status if 200 <= status < 300 else 202

