    def scan_quackhead_dynamixels(self) -> Dict[str, Any]:
        response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "POST",
            "/quackhead/dynamixel/scan",
            payload={},
            timeout=15.0,
        )
        if not response.get("ok"):
            raise _head_settings_error(response, "unable to scan the QuackHead Dynamixel bus")
        result = response.get("payload") if isinstance(response.get("payload"), dict) else {}
        ids = result.get("ids") if isinstance(result.get("ids"), list) else []
        clean_ids = []
        for value in ids:
            if isinstance(value, bool):
                continue
            try:
                item = int(value)
            except (TypeError, ValueError):
                continue
            if 1 <= item <= 252 and item not in clean_ids:
                clean_ids.append(item)
        clean_ids.sort()
        return {
            "ok": True,
            "head": BDX_HEAD_NAME,
            "baud": int(result.get("baud") or 0),
            "count": len(clean_ids),
            "ids": clean_ids,
            "message": str(result.get("message") or (
                f"Found {len(clean_ids)} Dynamixel{'s' if len(clean_ids) != 1 else ''}"
                if clean_ids else "No Dynamixels responded"
            )),
        }

