    def _local_update_command(self, arguments: List[str], *, timeout: float = 15.0) -> Dict[str, Any]:
        helper = Path(UPDATE_HELPER)
        if not helper.is_file() or not os.access(str(helper), os.X_OK):
            return {
                "ok": False,
                "available": False,
                "role": "body",
                "message": f"update helper is not installed: {UPDATE_HELPER}",
            }
        command = [UPDATE_HELPER, *arguments]
        if os.geteuid() != 0:
            sudo = shutil.which("sudo")
            if not sudo:
                return {"ok": False, "available": False, "role": "body", "message": "sudo is not installed"}
            command = [sudo, "-n", *command]
        result = _command(command, timeout=timeout)
        parsed = _last_json_object(result.get("stdout") or result.get("stderr") or "")
        if not result.get("ok") or not parsed:
            return {
                "ok": False,
                "available": False,
                "role": "body",
                "message": str(parsed.get("message") or result.get("message") or "body update helper failed"),
            }
        parsed.setdefault("available", True)
        return parsed

    @staticmethod
    def _normalize_update_status(value: Dict[str, Any], role: str) -> Dict[str, Any]:
        result = dict(value or {})
        result.setdefault("role", role)
        result.setdefault("available", bool(result.get("ok")))
        result.setdefault("state", "unavailable" if not result.get("available") else "idle")
        result.setdefault("active", result.get("state") in {"checking", "downloading", "installing", "rebooting"})
        result.setdefault("update_available", False)
        result.setdefault("downloaded", False)
        result.setdefault("can_download", bool(result.get("update_available") and not result.get("downloaded") and not result.get("active")))
        result.setdefault("can_install", bool(result.get("update_available") and result.get("downloaded") and not result.get("active")))
        result.setdefault("log_tail", [])
        return result

    def body_update_status(self) -> Dict[str, Any]:
        return self._normalize_update_status(self._local_update_command(["status"]), "body")

    def head_update_status(self) -> Dict[str, Any]:
        response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "GET",
            "/update",
            timeout=3.0,
        )
        payload = response.get("payload") if isinstance(response.get("payload"), dict) else {}
        if response.get("ok"):
            payload.setdefault("available", True)
            return self._normalize_update_status(payload, "head")
        return self._normalize_update_status({
            "ok": False,
            "available": False,
            "role": "head",
            "state": "offline",
            "message": str(payload.get("message") or response.get("message") or "head update service is unavailable"),
        }, "head")

    def update_status(self) -> Dict[str, Any]:
        body = self.body_update_status()
        head = self.head_update_status()
        head_complete = (
            bool(head.get("available"))
            and not bool(head.get("active"))
            and (
                not bool(head.get("update_available"))
                or (
                    bool(head.get("target_release"))
                    and str(head.get("current_release") or "") == str(head.get("target_release") or "")
                    and str(head.get("state") or "") == "complete"
                )
            )
        )
        active = bool(body.get("active") or head.get("active"))
        return {
            "ok": True,
            "body": body,
            "head": head,
            "active": active,
            "head_ready_for_body": head_complete,
            "can_download": bool(body.get("can_download") or head.get("can_download")),
            "checked_at": time.time(),
        }

    def start_update_action(self, action: str, target: str = "both") -> Dict[str, Any]:
        action = str(action or "").strip().lower()
        target = str(target or "both").strip().lower()
        if action not in {"check", "download", "install"}:
            raise ValueError(f"unsupported update action: {action}")
        if target not in {"body", "head", "both"}:
            raise ValueError(f"unsupported update target: {target}")
        if action == "install" and target == "both":
            raise ValueError("install one Orin at a time")

        started: Dict[str, Any] = {}
        if target in {"body", "both"}:
            started["body"] = self._normalize_update_status(
                self._local_update_command(["start", action], timeout=15.0),
                "body",
            )
        if target in {"head", "both"}:
            response = _json_http(
                BDX_HEAD_ETHERNET_IP,
                BDX_HEAD_SETTINGS_PORT,
                "POST",
                f"/update/{action}",
                payload={},
                timeout=8.0,
            )
            payload = response.get("payload") if isinstance(response.get("payload"), dict) else {}
            if response.get("ok"):
                started["head"] = self._normalize_update_status(payload, "head")
            else:
                started["head"] = self._normalize_update_status({
                    "ok": False,
                    "available": False,
                    "role": "head",
                    "message": str(payload.get("message") or response.get("message") or f"unable to start head {action}"),
                }, "head")

        if not any(bool(item.get("ok")) for item in started.values()):
            message = "; ".join(str(item.get("message") or "update start failed") for item in started.values())
            raise RuntimeError(message)
        return {"ok": True, "started": started, "status": self.update_status()}

