    def upload_head_sound(self, name: str, local_path: Path) -> Dict[str, Any]:
        path = Path(local_path)
        if not path.is_file():
            raise FileNotFoundError(str(path))
        relative = str(name or "").strip().replace("\\", "/")
        if not relative:
            raise ValueError("sound name is required")
        connection = http.client.HTTPConnection(BDX_HEAD_ETHERNET_IP, BDX_HEAD_SETTINGS_PORT, timeout=30.0)
        encoded = quote(relative, safe="/")
        size = int(path.stat().st_size)
        try:
            connection.putrequest("PUT", f"/sounds/{encoded}")
            connection.putheader("Host", f"{BDX_HEAD_NAME}:{BDX_HEAD_SETTINGS_PORT}")
            connection.putheader("Accept", "application/json")
            connection.putheader("Content-Type", "application/octet-stream")
            connection.putheader("Content-Length", str(size))
            connection.putheader("Connection", "close")
            connection.endheaders()
            with path.open("rb") as source:
                while True:
                    chunk = source.read(1024 * 1024)
                    if not chunk:
                        break
                    connection.send(chunk)
            response = connection.getresponse()
            raw = response.read(64 * 1024)
            try:
                payload = json.loads(raw.decode("utf-8")) if raw else {}
            except Exception:
                payload = {}
            result = {
                "ok": 200 <= int(response.status) < 300 and payload.get("ok", True) is not False,
                "status": int(response.status),
                "payload": payload if isinstance(payload, dict) else {},
                "message": str((payload or {}).get("message") or f"HTTP {int(response.status)}"),
            }
        except (OSError, http.client.HTTPException) as exc:
            result = {"ok": False, "status": 0, "payload": {}, "message": str(exc)}
        finally:
            connection.close()
        if not result.get("ok"):
            raise _head_settings_error(result, "unable to copy sound to head")
        payload = result.get("payload") if isinstance(result.get("payload"), dict) else {}
        payload.setdefault("ok", True)
        return payload

