    @staticmethod
    def _linux_password(value: Any) -> str:
        password = str(value or "")
        if any(char in password for char in "\r\n\0:"):
            raise ValueError("Linux password may not contain a colon, NUL, or newline")
        if len(password) < 8:
            raise ValueError("Linux password must contain at least 8 characters")
        if len(password) > 128:
            raise ValueError("Linux password must contain at most 128 characters")
        return password

    def _duck_password_command(self, payload: Dict[str, Any], *, timeout: float = 20.0) -> Dict[str, Any]:
        helper = Path(DUCK_PASSWORD_HELPER)
        if not helper.is_file() or not os.access(str(helper), os.X_OK):
            raise RuntimeError(f"duck password helper is not installed: {DUCK_PASSWORD_HELPER}")
        command = [DUCK_PASSWORD_HELPER]
        if os.geteuid() != 0:
            sudo = shutil.which("sudo")
            if not sudo:
                raise RuntimeError("sudo is not installed")
            command = [sudo, "-n", *command]
        result = _command(command, input_text=json.dumps(payload, separators=(",", ":")), timeout=timeout)
        parsed = _last_json_object(result.get("stdout") or result.get("stderr") or "")
        if not result.get("ok") or parsed.get("ok") is False:
            detail = str(parsed.get("message") or result.get("message") or "duck password helper failed")
            raise RuntimeError(detail)
        if not parsed:
            raise RuntimeError("duck password helper returned no JSON result")
        return parsed

    def duck_account_status(self) -> Dict[str, Any]:
        try:
            body = self._duck_password_command({"action": "check"}, timeout=8.0)
            body_available = True
        except Exception as ex:
            body = {"ok": False, "message": str(ex), "account": "duck"}
            body_available = False

        response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "GET",
            "/account",
            timeout=3.0,
        )
        payload = response.get("payload") if isinstance(response.get("payload"), dict) else {}
        if response.get("ok"):
            head = payload
            head_available = bool(payload.get("available", True))
        else:
            head = {
                "ok": False,
                "available": False,
                "account": "duck",
                "message": str(payload.get("message") or response.get("message") or "head account service is unavailable"),
            }
            head_available = False
        return {
            "ok": body_available and head_available,
            "available": body_available and head_available,
            "account": "duck",
            "body": body,
            "head": head,
            "message": (
                "The duck account password can be updated on both Orins."
                if body_available and head_available
                else "The duck account password cannot be updated until both Orins report the password helper."
            ),
        }

    def set_duck_password(self, value: Any) -> Dict[str, Any]:
        password = self._linux_password(value)
        # Verify both endpoints before changing either account. Apply the head
        # first, then the body. The body helper was preflighted, so a partial
        # update is unlikely; if it occurs, retrying the same password repairs it.
        self._duck_password_command({"action": "check"}, timeout=8.0)
        head_status = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "GET",
            "/account",
            timeout=3.0,
        )
        if not head_status.get("ok"):
            raise _head_settings_error(head_status, "head account password service is unavailable")
        head_response = _json_http(
            BDX_HEAD_ETHERNET_IP,
            BDX_HEAD_SETTINGS_PORT,
            "POST",
            "/account/password",
            payload={"password": password},
            timeout=20.0,
        )
        if not head_response.get("ok"):
            raise _head_settings_error(head_response, "unable to update the head duck password")
        body = self._duck_password_command({"action": "set", "password": password}, timeout=20.0)
        return {
            "ok": True,
            "account": "duck",
            "body": body,
            "head": head_response.get("payload") or {},
            "message": "Linux duck password updated on the head and body Orins.",
        }

    def _mdns_status(self) -> Dict[str, Any]:
        if not Path(MDNS_HELPER).is_file():
            return {
                "ok": False,
                "available": False,
                "system_hostname": "",
                "internal_hostname": "bdx-body",
                "internal_host_aliases": ["bdx-body", "bdx-head"],
                "external_hostname": "",
                "message": f"Duck identity helper is not installed: {MDNS_HELPER}",
            }
        result = _command([MDNS_HELPER, "status", "--json"], timeout=6.0)
        payload = _last_json_object(result.get("stdout", ""))
        if result.get("ok") and payload:
            return payload
        return {
            "ok": False,
            "available": False,
            "system_hostname": "",
            "internal_hostname": "bdx-body",
            "internal_host_aliases": ["bdx-body", "bdx-head"],
            "external_hostname": "",
            "message": str(payload.get("message") or result.get("message") or "Duck identity is unavailable"),
        }

    def _apply_mdns_identity(self, duck_name: str) -> Dict[str, Any]:
        result = _command(
            ["sudo", "-n", MDNS_HELPER, "set", "--json"],
            timeout=12.0,
            input_text=json.dumps({"duck_name": duck_name}) + "\n",
        )
        payload = _last_json_object(result.get("stdout", ""))
        if not result.get("ok") or not payload.get("ok"):
            raise RuntimeError(str(payload.get("message") or result.get("message") or "unable to update the Duck hostname"))
        return payload

    def capabilities(self) -> Dict[str, Any]:
        return {
            "body_wifi_cli": self.body_wifi_cli,
            "body_wifi_cli_installed": Path(self.body_wifi_cli).is_file() and os.access(self.body_wifi_cli, os.X_OK),
            "update_helper": UPDATE_HELPER,
            "update_helper_installed": Path(UPDATE_HELPER).is_file() and os.access(UPDATE_HELPER, os.X_OK),
            "duck_password_helper": DUCK_PASSWORD_HELPER,
            "duck_password_helper_installed": Path(DUCK_PASSWORD_HELPER).is_file() and os.access(DUCK_PASSWORD_HELPER, os.X_OK),
            "mdns_helper": MDNS_HELPER,
            "mdns_helper_installed": Path(MDNS_HELPER).is_file() and os.access(MDNS_HELPER, os.X_OK),
            "nmcli": bool(shutil.which("nmcli")),
            "head_settings_address": f"{BDX_HEAD_ETHERNET_IP}:{BDX_HEAD_SETTINGS_PORT}",
        }

    def snapshot(self) -> Dict[str, Any]:
        with self._identity_lock:
            identity = _load_identity(self.path)
        return {
            "settings_api_version": SETTINGS_API_VERSION,
            "settings": identity,
            "hostnames": self._mdns_status(),
            "body_wifi": self._body_wifi_snapshot(),
            "head": self._head_snapshot(),
            "access_paths": {
                "body_ethernet": f"{BDX_BODY_ETHERNET_IP}:{BDX_WEB_PORT}",
                "head_ethernet": f"{BDX_HEAD_ETHERNET_IP}:{BDX_WEB_PORT}",
                "head_access_point": f"192.168.51.1:{BDX_WEB_PORT}",
                "usb": f"192.168.55.1:{BDX_WEB_PORT}",
            },
            "capabilities": self.capabilities(),
            "duck_account": self.duck_account_status(),
            "job": self.job(),
            "checked_at": time.time(),
        }

    def scan_wifi(self) -> Dict[str, Any]:
        result = self._body_wifi_command(["--scan", "--json"], timeout=25.0)
        raw_networks = result.get("networks") if isinstance(result.get("networks"), list) else []
        networks: List[Dict[str, Any]] = []
        for raw in raw_networks:
            if not isinstance(raw, dict):
                continue
            network = dict(raw)
            network.update(classify_advertised_security(network.get("security")))
            networks.append(network)
        return {
            "ok": True,
            "policy": {
                "mode": "wpa2-only",
                "wpa3_allowed": False,
                "transition_allowed": True,
            },
            "networks": networks,
            "scanned_at": result.get("scanned_at", time.time()),
        }

    def save_identity(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        duck_name = self._plain_text(payload.get("duck_name"), "duck_name", max_len=64) or DEFAULT_DUCK_NAME
        with self._identity_lock:
            previous = _load_identity(self.path)
            _save_identity(self.path, duck_name)
            if Path(MDNS_HELPER).is_file():
                try:
                    hostnames = self._apply_mdns_identity(duck_name)
                except Exception:
                    _save_identity(self.path, previous.get("duck_name", ""))
                    try:
                        self._apply_mdns_identity(previous.get("duck_name", ""))
                    except Exception:
                        pass
                    raise
            else:
                hostnames = self._mdns_status()
        return {"ok": True, "settings": {"duck_name": duck_name}, "hostnames": hostnames}

    def job(self) -> Dict[str, Any]:
        with self._job_lock:
            return json.loads(json.dumps(self._job))

    def _start_job(self, component: str, message: str, worker: Callable[[], Dict[str, Any]]) -> Dict[str, Any]:
        with self._job_lock:
            if self._job.get("state") == "running":
                raise RuntimeError("another settings operation is already running")
            self._job_serial += 1
            job_id = self._job_serial
            self._job = {
                "id": job_id,
                "state": "running",
                "component": component,
                "message": message,
                "started_at": time.time(),
                "finished_at": None,
            }

        def run() -> None:
            try:
                result = worker()
            except Exception as ex:
                with self._job_lock:
                    if self._job.get("id") == job_id:
                        self._job.update({
                            "state": "error",
                            "message": str(ex),
                            "finished_at": time.time(),
                        })
                return
            with self._job_lock:
                if self._job.get("id") == job_id:
                    self._job.update({
                        "state": "complete",
                        "message": "Settings applied.",
                        "result": result,
                        "finished_at": time.time(),
                    })

        threading.Thread(target=run, name=f"puddleduck-settings-{component}", daemon=True).start()
        return self.job()

    def start_body_wifi(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        ssid = self._ssid(payload.get("ssid"))
        priority = self._priority(payload.get("priority", 50))
        hidden = _truthy(payload.get("hidden"))
        open_network = _truthy(payload.get("open"))
        password = self._psk(payload.get("password"), "Wi-Fi password")
        if open_network and password:
            raise ValueError("an open network cannot also have a password")

        stored = self._body_profiles()
        existing = next(
            (item for item in stored.get("profiles", []) if isinstance(item, dict) and item.get("ssid") == ssid),
            None,
        )
        if not existing and not open_network and not password:
            raise ValueError("enter a password for the new network, or mark it as open")
        if existing and existing.get("open") and not open_network and not password:
            raise ValueError("enter a password when changing an open network to a secured network")

        args = [
            "--ssid", ssid,
            "--priority", str(priority),
            "--hidden" if hidden else "--not-hidden",
            "--json",
        ]
        input_text = None
        if open_network:
            args.append("--open")
        elif password:
            args.append("--psk-stdin")
            input_text = f"{password}\n"

        return self._start_job(
            "body_wifi",
            f"Saving body Wi-Fi network {ssid}…",
            lambda: self._body_wifi_command(args, input_text=input_text, timeout=90.0),
        )

    def start_delete_body_wifi(self, ssid_value: Any) -> Dict[str, Any]:
        ssid = self._ssid(ssid_value)
        return self._start_job(
            "body_wifi",
            f"Removing body Wi-Fi network {ssid}…",
            lambda: self._body_wifi_command(["--delete", ssid, "--json"], timeout=90.0),
        )

    def start_head_ap(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        name = self._head_ap_name(payload.get("name"))
        password = self._psk(payload.get("password"), "access-point password")

        def apply() -> Dict[str, Any]:
            response = _json_http(
                BDX_HEAD_ETHERNET_IP,
                BDX_HEAD_SETTINGS_PORT,
                "POST",
                "/head-ap",
                payload={"head_ap_name": name, "head_ap_password": password},
                timeout=95.0,
            )
            if not response.get("ok"):
                raise RuntimeError(response.get("message") or "head settings service is unavailable")
            return response.get("payload") or {"ok": True}

        return self._start_job(
            "head_ap",
            "Applying the head access point…",
            apply,
        )
